311		if !strings.Contains(gMid.FailureReason, "作业 "+itoa(up.ID)) ||
312			!strings.Contains(gMid.FailureReason, "成功结果不可用") {
313			t.Fatalf("mid 须说明缺失上游的结果无法使用: %q", gMid.FailureReason)
314		}
315		gDown := waitStatus(t, s2, mid.ID+100, StatusFailed)
316		if gDown.BlockerID != up.ID {
317			t.Fatalf("down blocker=%d want missing root %d", gDown.BlockerID, up.ID)
318		}
319		if !strings.Contains(gDown.FailureReason, "直接上游作业 "+itoa(mid.ID)) ||
320			!strings.Contains(gDown.FailureReason, "阻断根因为作业 "+itoa(up.ID)) {
