// writeRawRecord 直接把给定记录结构序列化落盘，用于构造旧格式单依赖记录。
func writeRawRecord(t *testing.T, dir string, id uint64, r *jobRecord) {
	t.Helper()
	out, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := writeFileAtomic(dir, jobFileName(id), out, 0o600); err != nil {
		t.Fatal(err)
	}
}

