1	package numeric
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"strings"
11		"testing"
12		"time"
13	)
14	
15	// 本文件覆盖“读取规则接受的合法记录使用带额外后缀的文件名”这一形态：
16	// 作业号由记录内容识别，单份记录的名称不同于默认命名并不等于存在两个作业。
17	// 恢复改写与后续状态更新（运行、完成、失败、取消）都必须写回原来那一份
18	// 正式文件，不能按作业号另写默认命名的记录而同号旧记录原样保留——否则
19	// 下一次打开会因重复作业号拒绝打开。
20	
21	// suffixedRecordName 给出作业 id 的一份合法但非默认的记录文件名。
22	func suffixedRecordName(id uint64) string {
23		return fmt.Sprintf("job-%d-saved.json", id)
24	}
25	
26	// assertNoDefaultRecord 断言默认命名的记录文件不存在（没有制造同号副本）。
27	func assertNoDefaultRecord(t *testing.T, dir string, id uint64) {
28		t.Helper()
29		if _, err := os.Stat(filepath.Join(dir, jobFileName(id))); !errors.Is(err, fs.ErrNotExist) {
30			t.Fatalf("默认命名的同号记录不应出现（作业 %d）：stat err=%v", id, err)
31		}
32	}
33	
34	// 排队记录以非默认名称恢复后继续计算：进入运行、完成计算都写回原文件，
35	// 目录中始终只有那一份正式记录；关闭再开读取到更新后的成功状态与完整归档，
36	// 其他作业的记录不被移动或重写。
37	func TestRestoredQueuedJobWithSuffixedFileNameUpdatesSameFile(t *testing.T) {
38		dir := t.TempDir()
39		s, err := Open(dir, WithClock(newManualClock()))
40		if err != nil {
41			t.Fatal(err)
42		}
43		started, block, _, _, _ := gateCompute(t, s)
44		block(1)
45		head := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
46		waitStarted(t, started, head.ID)
47		q := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "q", Values: []int64{5}, Seed: 2})
48		if err := s.Close(); err != nil { // head 被标记为中断失败，q 仍是排队记录
49			t.Fatal(err)
50		}
51	
52		// 把 q 的正式记录换成带额外后缀的合法名称：读取规则接受它，
53		// 作业号由记录内容识别，这不是第二份作业。
54		custom := suffixedRecordName(q.ID)
55		if err := os.Rename(filepath.Join(dir, jobFileName(q.ID)), filepath.Join(dir, custom)); err != nil {
56			t.Fatal(err)
57		}
58		headBefore, err := os.ReadFile(filepath.Join(dir, jobFileName(head.ID)))
59		if err != nil {
60			t.Fatal(err)
61		}
62	
63		s2, err := Open(dir) // 单份记录名称不标准，不等于存在两个作业，不能拒绝打开
64		if err != nil {
65			t.Fatalf("open with suffixed record name: %v", err)
66		}
67		done := waitStatus(t, s2, q.ID, StatusSucceeded)
68		if done.Archive == nil || done.Archive.Sum != 5 {
69			t.Fatalf("restored queued job must run to success: %+v", done)
70		}
71	
72		// 运行与完成都写回原文件：目录中只有 custom 这一份作业 q 的记录。
73		assertNoDefaultRecord(t, dir, q.ID)
74		data, err := os.ReadFile(filepath.Join(dir, custom))
75		if err != nil {
76			t.Fatal(err)
77		}
78		if !strings.Contains(string(data), `"status": "succeeded"`) {
79			t.Fatalf("成功状态必须写回原记录文件：\n%s", data)
80		}
81		// 其他作业的记录不被这次更新移动或重写。
82		headAfter, err := os.ReadFile(filepath.Join(dir, jobFileName(head.ID)))
83		if err != nil {
84			t.Fatal(err)
85		}
86		if !bytes.Equal(headBefore, headAfter) {
87			t.Fatal("其他作业的记录不应被重写")
88		}
89		if err := s2.Close(); err != nil {
90			t.Fatal(err)
91		}
92	
93		// 再次打开：系统没有制造同号副本，打开成功并读到更新后的完整归档。
94		s3, err := Open(dir)
95		if err != nil {
96			t.Fatalf("reopen after in-place update: %v", err)
97		}
98		defer s3.Close()
99		g, err := s3.Get(q.ID)
100		if err != nil {
101			t.Fatal(err)
102		}
103		if g.Status != StatusSucceeded || g.Archive == nil || g.Archive.Sum != 5 {
104			t.Fatalf("更新后的成功状态与归档应在重开后可读：%+v", g)
105		}
106	}
107	
108	// 上次关闭时仍在运行的记录以非默认名称恢复：改判失败只更新原记录文件，
109	// 重开后读到失败状态，不返回成功归档或实际输入。
110	func TestRestoredRunningRecordWithSuffixedFileNameFailedInPlace(t *testing.T) {
111		dir := t.TempDir()
112		when := time.Date(2026, 2, 3, 4, 5, 6, 0, time.UTC)
113		j := &storedJob{
114			id: 7, submitter: "a", requestID: "r7", seed: 3,
115			values: []int64{1, 2},
116			queuedAt: when, startedAt: when,
117			status: StatusRunning,
118		}
119		data, err := encodeRecord(j)
120		if err != nil {
121			t.Fatal(err)
122		}
123		custom := suffixedRecordName(j.id)
124		if err := writeFileAtomic(dir, custom, data, 0o600); err != nil {
125			t.Fatal(err)
126		}
127	
128		s, err := Open(dir)
129		if err != nil {
130			t.Fatal(err)
131		}
132		g, err := s.Get(j.id)
133		if err != nil {
134			t.Fatal(err)
135		}
136		if g.Status != StatusFailed || !strings.Contains(g.FailureReason, "计算被中断") ||
137			g.Archive != nil || len(g.EffectiveValues) != 0 {
138			t.Fatalf("中断的运行记录应改判失败：%+v", g)
139		}
140		// 失败改判写回原文件，不产生默认命名的同号副本。
141		out, err := os.ReadFile(filepath.Join(dir, custom))
142		if err != nil {
143			t.Fatal(err)
144		}
145		if !strings.Contains(string(out), `"status": "failed"`) {
146			t.Fatalf("失败改判必须写回原记录文件：\n%s", out)
147		}
148		assertNoDefaultRecord(t, dir, j.id)
149		if err := s.Close(); err != nil {
150			t.Fatal(err)
151		}
152	
153		// 再次打开：读到更新后的失败状态，不返回成功归档或实际输入。
154		s2, err := Open(dir)
155		if err != nil {
156			t.Fatalf("reopen after in-place failure update: %v", err)
157		}
158		defer s2.Close()
159		g2, err := s2.Get(j.id)
160		if err != nil {
161			t.Fatal(err)
162		}
163		if g2.Status != StatusFailed || g2.Archive != nil || len(g2.EffectiveValues) != 0 {
164			t.Fatalf("重开后应读到失败状态且无归档与实际输入：%+v", g2)
165		}
166	}
167	
168	// 取消已恢复的排队作业同样以原记录替换成功为生效条件：原文件无法替换时
169	// （即使默认命名对应的位置可写）返回实际保存错误，作业保持取消前状态，
170	// 不中止计算、不级联下游、不转到另一文件；写入条件恢复后重新取消生效，
171	// 取消记录仍写回原文件。
172	func TestCancelRestoredQueuedJobMustReplaceOriginalFile(t *testing.T) {
173		dir := t.TempDir()
174		when := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
175		// 一批各自合法的排队上游记录：本作业等待它们全部成功，worker 逐个处理
176		// 期间本作业保持排队。每条记录都很小，worker 单次落盘的持锁时间极短，
177		// 取消与状态查询不会被长时间挡在锁外；上游数量保证两次取消请求都
178		// 发生在本作业变为可运行之前。
179		const upstreams = 400
180		depIDs := make([]uint64, 0, upstreams)
181		for i := 1; i <= upstreams; i++ {
182			u := &storedJob{
183				id: uint64(i), submitter: "b",
184				values: []int64{1}, queuedAt: when, status: StatusQueued,
185			}
186			data, err := encodeRecord(u)
187			if err != nil {
188				t.Fatal(err)
189			}
190			if err := os.WriteFile(filepath.Join(dir, jobFileName(u.id)), data, 0o600); err != nil {
191				t.Fatal(err)
192			}
193			depIDs = append(depIDs, u.id)
194		}
195		q := &storedJob{
196			id: upstreams + 1, submitter: "a", requestID: "q", seed: 7,
197			values: []int64{5}, dependencies: depIDs,
198			queuedAt: when,
199			status:   StatusQueued,
200		}
201		qData, err := encodeRecord(q)
202		if err != nil {
203			t.Fatal(err)
204		}
205		custom := suffixedRecordName(q.id)
206		customPath := filepath.Join(dir, custom)
207		if err := os.WriteFile(customPath, qData, 0o600); err != nil {
208			t.Fatal(err)
209		}
210	
211		s, err := Open(dir)
212		if err != nil {
213			t.Fatal(err)
214		}
